import{F as e,_ as t,f as n,h as r,j as i,n as a}from"./chunks/shared.rYHlazZf.js";var o=JSON.parse(`{"title":"プラグインをインストール・管理する","description":"","frontmatter":{"title":"プラグインをインストール・管理する","docId":"user.plugins.index","translationKey":"user.plugins.index","locale":"ja","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"2892162f1f2ec94f8e5072f6689382b3c32c8546f2ad667a4651c721f597e84a","translationRevision":"1c35b20ff7f1ce9a75f795ec6dfd5e73ed344a4265f0428c5831359e6cab8d66","order":10},"headers":[],"relativePath":"ja/user/plugins/index.md","filePath":"ja/user/plugins/index.md","lastUpdated":1795735295000}`),s={name:`ja/user/plugins/index.md`};function c(a,o,s,c,l,u){let d=e(`TourFrame`);return i(),n(`div`,null,[o[0]||=r(`<h1 id="install-and-manage-plugins" tabindex="-1">プラグインをインストール・管理する <a class="header-anchor" href="#install-and-manage-plugins" aria-label="Permalink to “プラグインをインストール・管理する”">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">目的と前提条件 <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to “目的と前提条件”">​</a></h2><p>連携を追加し、要求アクセスを確認してアクションが使えることを確かめます。プラグインの OS、アーキテクチャ、ホストバージョンに対応するデスクトップパッケージが必要です。リモートカタログとダウンロードにはネットワークが、一部のアカウント方式サービスには <a href="./../cloud/account.html">Cloud サインイン</a> も必要です。</p><h2 id="review-before-enabling" tabindex="-1">有効化前に確認する <a class="header-anchor" href="#review-before-enabling" aria-label="Permalink to “有効化前に確認する”">​</a></h2><ol><li><strong>プラグイン</strong> のインストール済み、探す、アップデートを確認します。探すはプラグイン項目だけを取得します。自動化テンプレートとプロファイルは <a href="./../automations/templates.html">自動化</a> にあります。</li><li>説明、バージョン、互換性、ランタイムを確認します。見慣れた表示名だけを信じず、発行者と要求機能・権限を確認します。</li><li>インストール画面でパッケージをプレビューし、確定前に正確なバージョン、署名、要求アクセス、既存版からの変更を読みます。</li><li>ジョブ結果を待ちます。ダウンロード、インストール、有効化は別段階で、カタログカードだけでは実行準備は完了していません。</li><li>プラグインの設定または接続を開き、専用欄だけにアドレスと認証情報を入力します。提供されていれば宣言済みの接続確認を使います。</li><li>有効化後、アクション種別やページの表示を確認します。強力な外部アクションを結び付ける前に、範囲を絞った<a href="./../automations/first-rule.html">ログ記録ルール</a> を作ります。</li></ol><p>プラグインはネイティブコードや別プロセスを実行できます。プロセス分離はクラッシュを切り離せても OS のサンドボックスではありません。信頼できる発行者のソフトウェアを使います。有効な署名は確認された出所を示しますが、すべての処理が用途に適するとは限りません。</p><h2 id="expected-result-and-status" tabindex="-1">期待される結果と提供状況 <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to “期待される結果と提供状況”">​</a></h2><p>パッケージ確認、インストールジョブ、設定、バージョン管理を利用できます。実際のアクションはマニフェスト、ホスト機能、外部サービスに依存します。イベントプロセッサーには専用パネルがあり、イベントに任意の分析フィールドを追加できます。生のフィールドとは区別されます。</p><h2 id="recovery" tabindex="-1">問題が起きたとき <a class="header-anchor" href="#recovery" aria-label="Permalink to “問題が起きたとき”">​</a></h2><p>失敗時はジョブのエラーから互換性、署名、ランタイム、取得の問題を読みます。エラーを消すために検証を弱めないでください。更新後の問題では保持版を確認し、可能ならロールバックします。無効化・削除前に依存する自動化を確認し、プラグインのデータと設定を<a href="./../preferences/backups.html">バックアップ</a> します。</p>`,10),t(d,{id:`plugin`,locale:`ja`,title:`デモ: プラグイン`}),o[1]||=r(`<h2 id="command-line-operations" tabindex="-1">コマンドライン操作 <a class="header-anchor" href="#command-line-operations" aria-label="Permalink to “コマンドライン操作”">​</a></h2><p>このガイドのすべての操作はCLIからも利用できます——オフライン、スクリプト可能、エージェント対応。使用法の行はパーサー構文であり、すべての言語で英語のままです。</p><table tabindex="0"><thead><tr><th>コマンド</th><th>概要</th></tr></thead><tbody><tr><td><code>tiktools plugin list</code></td><td>インストール済みプラグインを一覧表示</td></tr><tr><td><code>tiktools plugin get &lt;id&gt;</code></td><td>プラグインを1つ読み取る</td></tr><tr><td><code>tiktools plugin install &lt;file.plugin&gt; [--replace] &amp;#124; plugin install &lt;id[@version]&amp;#124;url&gt; [--yes] [--no-wait] [--allow-unsigned]</code></td><td>ファイル、id@version または url からインストール</td></tr><tr><td><code>tiktools plugin uninstall &lt;id&gt; [--purge]</code></td><td>プラグインをアンインストール <strong>破壊的</strong></td></tr><tr><td><code>tiktools plugin search &lt;query&gt; [--category c] [--page N]</code></td><td>レジストリでパッケージを検索</td></tr><tr><td><code>tiktools plugin inspect &lt;spec&gt;</code></td><td>インストール前にパッケージ仕様を検査</td></tr><tr><td><code>tiktools plugin outdated</code></td><td>更新可能なインストール済みプラグインを一覧表示</td></tr><tr><td><code>tiktools plugin update &lt;id&gt; [--version v] [--yes] [--no-wait]</code></td><td>プラグインを1つ更新</td></tr><tr><td><code>tiktools plugin update --all [--yes] [--no-wait]</code></td><td>すべての古いプラグインを更新</td></tr><tr><td><code>tiktools plugin rollback &lt;id&gt; [version] [--no-wait]</code></td><td>以前のバージョンにロールバック <strong>破壊的</strong></td></tr><tr><td><code>tiktools plugin versions &lt;id&gt;</code></td><td>プラグインの利用可能なバージョンを一覧表示</td></tr><tr><td><code>tiktools plugin pin &lt;id&gt;</code></td><td>プラグインを現在のバージョンにピン留め</td></tr><tr><td><code>tiktools plugin unpin &lt;id&gt;</code></td><td>バージョンのピン留めを解除</td></tr><tr><td><code>tiktools plugin policy &lt;id&gt; [--channel stable&amp;#124;beta] [--auto off&amp;#124;notify&amp;#124;patch&amp;#124;minor]</code></td><td>チャンネルと自動更新ポリシーを設定</td></tr><tr><td><code>tiktools plugin jobs</code></td><td>パッケージジョブを一覧表示</td></tr><tr><td><code>tiktools plugin job &lt;job-id&gt;</code></td><td>パッケージジョブを1つ検査</td></tr><tr><td><code>tiktools plugin cancel &lt;job-id&gt;</code></td><td>実行中のパッケージジョブをキャンセル <strong>破壊的</strong></td></tr><tr><td><code>tiktools plugin enable &lt;id&gt;</code></td><td>プラグインを有効化</td></tr><tr><td><code>tiktools plugin disable &lt;id&gt;</code></td><td>プラグインを無効化</td></tr><tr><td><code>tiktools plugin start &lt;id&gt;</code></td><td>プラグインを開始</td></tr><tr><td><code>tiktools plugin stop &lt;id&gt;</code></td><td>プラグインを停止 <strong>破壊的</strong></td></tr><tr><td><code>tiktools plugin settings get &lt;id&gt;</code></td><td>プラグイン設定を読み取る</td></tr><tr><td><code>tiktools plugin settings set &lt;id&gt; k=v...</code></td><td>プラグイン設定を書き込む</td></tr><tr><td><code>tiktools plugin settings reset &lt;id&gt;</code></td><td>プラグイン設定をリセット <strong>破壊的</strong></td></tr><tr><td><code>tiktools plugin health &lt;id&gt;</code></td><td>プラグインのヘルスチェック</td></tr><tr><td><code>tiktools plugin options &lt;action-type/field&gt;</code></td><td>アクションタイプまたはフィールドのオプション</td></tr><tr><td><code>tiktools plugin action &lt;type&gt; [--config json] [--live]</code></td><td>プラグインアクションを実行</td></tr><tr><td><code>tiktools plugin commands</code></td><td>インストール済みプラグインが提供するコマンドを一覧表示</td></tr><tr><td><code>tiktools plugin help [id]</code></td><td>提供されたコマンドを1つ説明</td></tr><tr><td><code>tiktools plugin &lt;id&gt; &lt;command&gt; [--params json] [--live]</code></td><td>プラグイン提供コマンドを呼び出す</td></tr></tbody></table><table tabindex="0"><thead><tr><th>コマンド</th><th>概要</th></tr></thead><tbody><tr><td><code>tiktools registry list</code></td><td>設定済みレジストリを一覧表示</td></tr><tr><td><code>tiktools registry refresh</code></td><td>レジストリメタデータを更新</td></tr><tr><td><code>tiktools registry package &lt;id&gt;</code></td><td>レジストリパッケージを1つ表示</td></tr><tr><td><code>tiktools registry cloud-catalog [--query q] [--after cursor] [--generation value] [--target name]</code></td><td>クラウドカタログを検索</td></tr><tr><td><code>tiktools registry cloud-summaries [--query q] [--cursor value] [--generation value] [--target name]</code></td><td>クラウドカタログのサマリーページ</td></tr><tr><td><code>tiktools registry cloud-versions &lt;id&gt; [--target name] [--generation value] [--cursor value]</code></td><td>クラウドカタログパッケージのバージョン</td></tr><tr><td><code>tiktools registry cloud-pagination</code></td><td>クラウドカタログのページネーション機能</td></tr><tr><td><code>tiktools registry defaults</code></td><td>デフォルトのレジストリ設定</td></tr></tbody></table><table tabindex="0"><thead><tr><th>コマンド</th><th>概要</th></tr></thead><tbody><tr><td><code>tiktools processor list</code></td><td>プロセッサーを一覧表示</td></tr><tr><td><code>tiktools processor status</code></td><td>プロセッサーパイプラインの状態</td></tr><tr><td><code>tiktools processor test &lt;plugin-id&gt; &lt;processor-id&gt; [event-json]</code></td><td>サンプルイベントに対してプロセッサーを1つ実行</td></tr></tbody></table><p>規約、JSON出力、破壊的操作のマーカーについては<a href="./../../developer/cli.html">完全なコマンドリファレンス</a>を参照してください。</p>`,6)])}var l=a(s,[[`render`,c]]);export{o as __pageData,l as default};